# 路由聚合
# app/api/v1/router.py
from fastapi import APIRouter
from app.api.v1.endpoints import products, users, order ,cart 



api_router = APIRouter()
# 第二层路由，负责聚合不同的功能模块（如商品管理、用户认证等），每个模块都定义了自己的 APIRouter 实例，最后在这里统一注册到 api_router 上
# APIRouter 是 FastAPI 提供的一个类，用于创建路由实例，可以将多个路由组织在一起，方便管理和维护

# 注册商品路由，前缀为 /products
api_router.include_router(products.router, prefix="/products", tags=["商品管理"])
# products.router 是在 app/api/v1/endpoints/products.py 中定义的 APIRouter 实例
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
api_router.include_router(users.router, prefix="/users", tags=["用户认证"]) # 添加用户路由

api_router.include_router(order.router, prefix="/order", tags=["订单管理"]) # 添加订单路由

api_router.include_router(cart.router, prefix="/cart", tags=["cart"]) # 添加购物车路由